<?php

declare(strict_types=1);

namespace Inilim\Tool\Method\Other;

function pagination(int $curPage,int $limitOnePage,int $countRecords){$obj=new class{/***@returnarray*/function getAll($curPage,$limitOnePage,$countRecords){$limitOnePage=\abs($limitOnePage);$countRecords=\abs($countRecords);$countPages=$this -> getCountPages($limitOnePage,$countRecords);$curPage=$this -> getValidCurPage($curPage,$countPages);return['pageCount'=>$countPages,'recordCount'=>$countRecords,'recordPerPage'=>$limitOnePage,'curPage'=>$curPage,'offset'=>$this -> offset($curPage,$countPages,$limitOnePage),'next'=>$this -> next($curPage,$countPages),'prev'=>$this -> prev($curPage,$countPages),'isLast'=>$this -> isLast($curPage,$countPages),'isFirst'=>$this -> isFirst($curPage)];}/***@returnint|null*/function next($curPage,$countPages){$curPage=$this -> getValidCurPage($curPage,$countPages);$countPages=$this -> prepareCountPages($countPages);if($curPage===$countPages||$countPages===1){return null;}return $curPage+1;}/***@returnint|null*/function prev($curPage,$countPages){$curPage=$this -> getValidCurPage($curPage,$countPages);if($curPage===1){return null;}return $curPage-1;}/***Получитьобщееколичествостраниц*@returnint<1,max>*/function getCountPages($limitOnePage,$countRecords){$limitOnePage=\abs($limitOnePage);if($limitOnePage===0){return 1;}$countRecords=\abs($countRecords);if($countRecords===0){return 1;}$c=\intval(\ceil($countRecords/$limitOnePage));return $c<=0?1:$c;}/***расчитываемoffsetдляsqlзапроса*@returnint<0,max>*/function offset($curPage,$countPages,$limitOnePage){$curPage=$this -> getValidCurPage($curPage,$countPages);$limitOnePage=\abs($limitOnePage);$offset=$curPage*$limitOnePage-$limitOnePage;return $offset<0?0:$offset;}/***@returnint<1,max>*/function getValidCurPage($curPage,$countPages){$curPage=$this -> prepareCurPage($curPage);if($curPage===1){return 1;}$countPages=$this -> prepareCountPages($countPages);return $curPage>$countPages?$countPages:$curPage;}/***@returnbool*/function isLast($curPage,$countPages){$countPages=$this -> prepareCountPages($countPages);$curPage=$this -> prepareCurPage($curPage);return $curPage>=$countPages;}/***@returnbool*/function isFirst($curPage){return $this -> prepareCurPage($curPage)===1;}/***@protected*@returnint<1,max>*/function prepareCurPage($curPage){return $curPage<=0?1:$curPage;}/***@protected*@returnint<1,max>*/function prepareCountPages($countPages){$countPages=\abs($countPages);return $countPages===0?1:$countPages;}};return $obj -> getAll($curPage,$limitOnePage,$countRecords);}